import type { CreateHost, Effect, Host, Outcome, PaymentView } from '../host.ts';

const MAX_REQUESTS = 3;

type Status = PaymentView['status'];

interface Payment {
  status: Status;
  authorized: number;
  captured: number;
  refunded: number;
  requests: number;
}

const ok = (): Outcome => ({ ok: true });
const refuse = (reason: string): Outcome => ({ ok: false, reason });
const isUnit = (amount: unknown): amount is number => amount === 1 || amount === 2;

const createHost: CreateHost = async () => {
  const payments = new Map<string, Payment>();
  const pending = new Map<string, Effect>();
  let nextEffect = 1;

  const request = (id: string, p: Payment): void => {
    p.requests += 1;
    const effectId = `e${nextEffect++}`;
    pending.set(effectId, { id: effectId, from: id, kind: 'card.authorize', data: { amount: p.authorized } });
  };

  const host: Host = {
    async authorize(id, amount) {
      if (!isUnit(amount)) return refuse('amount must be 1 or 2');
      if (payments.has(id)) return refuse('payment already exists');
      const p: Payment = { status: 'authorizing', authorized: amount, captured: 0, refunded: 0, requests: 0 };
      payments.set(id, p);
      request(id, p);
      return ok();
    },

    async timedOut(id) {
      const p = payments.get(id);
      if (!p) return refuse('unknown payment');
      if (p.status !== 'authorizing') return refuse('payment is not authorizing');
      if (p.requests >= MAX_REQUESTS) p.status = 'failed';
      else request(id, p);
      return ok();
    },

    async capture(id, amount) {
      const p = payments.get(id);
      if (!p) return refuse('unknown payment');
      if (!isUnit(amount)) return refuse('amount must be 1 or 2');
      if (p.status !== 'authorized') return refuse('payment is not authorized');
      if (amount > p.authorized) return refuse('amount exceeds authorised amount');
      p.captured = amount;
      p.status = 'captured';
      return ok();
    },

    async void(id) {
      const p = payments.get(id);
      if (!p) return refuse('unknown payment');
      if (p.status !== 'authorized') return refuse('payment is not authorized');
      p.status = 'voided';
      return ok();
    },

    async refund(id, amount) {
      const p = payments.get(id);
      if (!p) return refuse('unknown payment');
      if (!isUnit(amount)) return refuse('amount must be 1 or 2');
      if (p.status !== 'captured') return refuse('payment is not captured');
      if (p.refunded + amount > p.captured) return refuse('refund exceeds captured amount');
      p.refunded += amount;
      if (p.refunded === p.captured) p.status = 'refunded';
      return ok();
    },

    async payment(id) {
      const p = payments.get(id);
      return p ? { ...p } : null;
    },

    async pendingEffects() {
      return [...pending.values()].map((e) => ({ ...e, data: { ...e.data } }));
    },

    async completeEffect(effectId, outcome) {
      const e = pending.get(effectId);
      if (!e) return;
      pending.delete(effectId);
      const p = payments.get(e.from);
      if (!p || p.status !== 'authorizing') return;
      p.status = outcome === 'ok' ? 'authorized' : 'declined';
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('happy path', async () => {
  const h = await create();
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  assert.equal((await h.authorize('q', 3)).ok, false);
  assert.equal((await h.capture('p', 1)).ok, false);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ ...e, id: '' }, { id: '', from: 'p', kind: 'card.authorize', data: { amount: 2 } });
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.capture('p', 2)).ok, true);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.equal((await h.payment('p'))!.status, 'captured');
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  assert.equal(await h.payment('x'), null);
});

test('timeouts', async () => {
  const h = await create();
  await h.authorize('p', 1);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.pendingEffects()).length, 3);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  const es = await h.pendingEffects();
  await h.completeEffect(es[0].id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('decline and void', async () => {
  const h = await create();
  await h.authorize('a', 1); await h.authorize('b', 1);
  for (const e of await h.pendingEffects()) await h.completeEffect(e.id, e.from === 'a' ? 'failed' : 'ok');
  assert.equal((await h.payment('a'))!.status, 'declined');
  assert.equal((await h.capture('b', 2)).ok, false);
  assert.equal((await h.void('b')).ok, true);
  assert.equal((await h.void('b')).ok, false);
  assert.equal((await h.capture('b', 1)).ok, false);
  assert.equal((await h.void('zz')).ok, false);
});
EOF
npx tsc --noEmit -p . && npm test 2>&1 | tail -12

